"推薦人": "Referrals",
"不想提供 Email 也可以只用名稱與大頭貼登入；之前已經用 Google 確認過的話，要到「我的 → 隱私」關閉「讓我推薦的跑友用 Gmail 找到我」。": "Don’t want to share your email? You can sign in with just your name and profile photo. If you’ve confirmed with Google before, go to Me → Privacy and turn off “Let runners I referred find me by Gmail”.",
"只用名稱與大頭貼登入": "Sign in with name and photo only",
"只取得你的 Google 名稱和大頭貼；Email 只拿來算一組無法還原的查詢碼，讓你推薦的跑友找得到你，Email 本身不保存。不會讀取你的信件或雲端資料。": "We only get your Google name and profile photo. Your email is only used to compute a one-way lookup code so runners you referred can find you; the email itself is never stored. We never read your mail or cloud files.",
"協會開放「推薦人」時，可以填是誰介紹你來的：選跑友帳號（對方會收到通知，可以按「不是我」移除），或只填名字（最多 20 字）；推薦關係只有會員管理權限的協會幹部看得到，每次查看都有稽核紀錄": "When the association turns on Referrals, you can say who introduced you: a runner account (they are notified and can tap \"Not me\") or just a name (up to 20 characters). Only officers with member-management permission can see referrals, and every view is logged",
"用 Google 登入時，Email 只拿來算一組無法還原的查詢碼，讓你推薦的跑友用 Gmail 找到你；Email 本身不保存，可以在「我的 → 隱私」關閉": "When you sign in with Google, your email is only used to compute a one-way lookup code so runners you referred can find you by Gmail. The email itself is never stored, and you can turn this off in Me → Privacy",
"識別類（C001）：姓名、暱稱、Google 帳號的顯示名稱與大頭貼、電話（選填）；協會開放「推薦人」時，另外保存一組由你的 Google Email 算出、無法還原的查詢碼（不保存 Email 本身），讓你推薦的跑友輸入你的 Gmail 時找得到你，可以在「我的 → 隱私」關閉，關閉後立即刪除。": "Identification (C001): name, nickname, Google display name and profile photo, phone (optional). When the association turns on Referrals, we also keep a one-way lookup code computed from your Google email (never the email itself) so runners you referred can find you by Gmail; you can turn this off in Me → Privacy, which deletes it immediately.",
"推薦人（選填）：誰介紹你加入，可以選跑友帳號或只填名字；用途是團購或活動聯絡不上時，協會幹部能透過介紹人協助聯繫。選跑友帳號時，對方會收到通知並看得到你的名字，對方可以按「不是我」移除；推薦人刪除帳號後只顯示「已刪除」，不留名字。": "Referrer (optional): who introduced you, as a runner account or just a name. It lets association officers reach you through your referrer when a group order or event can't contact you. If you pick an account, that person is notified, sees your name and can tap \"Not me\" to remove it; if your referrer deletes their account, only \"deleted\" is shown, with no name.",
"對象：依職務最小權限開放給協會幹部；分團團長與幹部可以看自己分團的名冊（不含電話）與該分團活動的報名及問卷結果；協會開放團員揪團時，團員自己發起的揪團由發起人擔任主辦，看得到報名者的姓名、給主辦的備註與攜伴姓名（不含電話與繳費資料）；電話完整號碼只有行政人員看得到。賽事報名資料只在你報名「代為團體報名」的活動並勾選同意後，提供給該活動的主辦幹部，用來向賽事主辦單位送出團體報名，每次下載都留有稽核紀錄。通訊地址存檔前會送到中華郵政的 3+3 郵遞區號服務核對寫法並補上郵遞區號，只傳送地址文字。練跑地圖的「附近即時影像」由本站伺服器向政府公開攝影機取得畫面再轉給你，你的 IP 與位置不會傳給影像來源，本站也不保存影像。推薦關係（誰推薦誰）只有具會員管理權限的協會幹部（理事長、理事、監事、行政人員）在管理後台看得到，監事只能查看，每次查看都留有稽核紀錄；分團幹部看不到。不提供給第三方行銷使用。": "Recipients: Association officers, on a least-privilege basis by role. Sub-club leads and officers can see their own sub-club’s roster (without phone numbers) and the sign-ups and survey results for that sub-club’s events. When the Association turns on member meetups, the member who starts a meetup is its organizer and can see the sign-ups’ names, notes to the organizer, and guest names (no phone numbers or payment details). Only administrative staff can see full phone numbers. Race registration details are shared only with the organizing officer of an event you sign up for with group registration and consent to, so they can submit the group entry to the race organizer; every download is audit-logged. Before saving, your mailing address is checked against Chunghwa Post’s 3+3 postal code service to fix its format and add the postal code; only the address text is sent. For “Nearby live cameras” on the Run Map, our server fetches images from public government cameras and passes them to you; your IP address and location are never sent to the camera source, and we do not store the images. Who referred whom is visible only to association officers with member-management permission (chair, directors, supervisors, staff) in the admin console; supervisors can only view, and every view is logged. Sub-club officers cannot see it. Nothing is shared with third parties for marketing.",
