"團練、揪跑、賽事提醒與國定假日": "Group runs, social runs, race reminders, and public holidays",
"團練、揪跑與幹部設定的賽事提醒會自動出現在 iPhone、Google 行事曆，有變動也會跟著更新。訂閱網址等同你的個人鑰匙，不要分享給別人。": "Group runs, social runs, and race reminders set by officers appear automatically in iPhone and Google calendars and stay up to date. The subscription URL works like your personal key, so don't share it.",
"團練公告、報名接龍和每週課表，都收在這裡。用 Google 登入就會記得你的組別，報名不用再打名字。": "Group run posts, signup lists, and weekly training plans, all in one place. Sign in with Google and we’ll remember your group, so you won’t have to type your name to sign up.",
