"姓名、暱稱、組別、主團、餐點偏好、報名與訓練紀錄；賽事報名資料加密保存；電話只有行政人員看得到完整號碼。": "Name, nickname, group, home club, meal preference, signups, and training logs. Race entry details are stored encrypted. Only staff can see your full phone number.",
"姓名、暱稱、跑團或會員編號": "Name, nickname, running club, or member number",
"姓名與組別是報名與排課表的必要資料；不提供就無法報名活動。賽事報名資料只在報名「代為團體報名」的活動時需要，不填不影響其他功能。其他欄位都是選填。": "Name and group are required for signups and training plans; without them you can’t sign up for events. Race entry details are only needed for “group entry by officers” events, and leaving them blank doesn’t affect other features. All other fields are optional.",
