"對象：依職務最小權限開放給協會幹部；分團團長與幹部可以看自己分團的名冊（不含電話）與該分團活動的報名及問卷結果；電話完整號碼只有行政人員看得到。賽事報名資料只在你報名「代為團體報名」的活動並勾選同意後，提供給該活動的主辦幹部，用來向賽事主辦單位送出團體報名，每次下載都留有稽核紀錄。不提供給第三方行銷使用。": "Recipients: Association officers on a least-privilege basis by role. Sub-club Captains and officers can see their own sub-club’s roster (without phone numbers) and signups and survey results for its events. Only Staff can see full phone numbers. Race entry details are shared only after you sign up for a “group entry by officers” event and give consent, with that event’s organizing officers, solely to submit the group entry to the race organizer. Every download is recorded in the audit log. Data is never shared with third parties for marketing.",
