"歡迎來到耕跑團": "Welcome to Cultivation in Life Run",
"歡迎加入耕跑團！先看看今天的課表和接下來的團練；主團會由管理員幫你設定，也可以到「我的 → 主團與分團」申請加入分團。": "Welcome to Cultivation in Life Run! Check today’s plan and upcoming group runs. An admin will set your home club, or apply to a sub-club under Me → Home club & sub-clubs.",
"歡迎加入！": "Welcome!",
"歡迎加入！先到「個人資料」確認項目和組別；主團會由管理員設定。": "Welcome! First check your event and group in “Profile”. An admin will set your home club.",
