"每個最多 4 個字，留空就用預設。每個人也可以在「我的 → 通知與裝置」選擇只顯示圖示。": "Up to 4 characters each. Leave blank to use the default. Anyone can also choose icons only in “Me → Notifications & devices”.",
"每公里分段": "Splits per km",
"每天凌晨 3 點自動把資料庫加密備份（AES-GCM），保留 35 天。還原用 tools/restore-backup.mjs，金鑰另外保存在理事長的電腦與密碼管理器。": "Every day at 3 a.m. the database is backed up with AES-GCM encryption and kept for 35 days. Restore with tools/restore-backup.mjs; the key is kept on the President’s computer and in a password manager.",
