"每次下載都會留下稽核紀錄；你可以隨時修改或刪除": "Every download is recorded in the audit log. You can edit or delete this anytime.",
"每筆紀錄都有只有系統知道的簽章，每天再串成一條摘要鏈。有人直接改或刪資料庫裡的紀錄，這裡就會顯示異常。": "Each record has a signature only the system knows, and each day’s records are chained into a digest. If anyone edits or deletes a record directly in the database, it shows up here as an anomaly.",
