"跑友可以填是誰介紹他來的（用 Gmail 找跑友帳號，或只填名字）；會員管理權限的幹部在「管理後台 → 會員 → 推薦族譜」查看。打開前請先在 Google Cloud 的 OAuth 同意畫面加上 Email 範圍；打開後 Google 登入會多問一次 Email 授權。關閉後不能新增，已經填的保留，本人仍可移除": "Runners can say who introduced them (find a runner account by Gmail, or just enter a name). Officers with member-management permission can view it in Admin → Members → Referral tree. Before turning this on, add the Email scope to the OAuth consent screen in Google Cloud; once on, Google sign-in asks for email permission one more time. When off, no new referrers can be added; existing ones are kept and runners can still remove their own",
