"你填的通訊地址（選填）會送到中華郵政的郵遞區號服務核對寫法、補上郵遞區號，只送地址文字，不含姓名": "Your mailing address (optional) is checked against Chunghwa Post’s postal code service to fix its format and add the postal code. Only the address is sent, never your name.",
"對象：依職務最小權限開放給協會幹部；分團團長與幹部可以看自己分團的名冊（不含電話）與該分團活動的報名及問卷結果；電話完整號碼只有行政人員看得到。賽事報名資料只在你報名「代為團體報名」的活動並勾選同意後，提供給該活動的主辦幹部，用來向賽事主辦單位送出團體報名，每次下載都留有稽核紀錄。通訊地址存檔前會送到中華郵政的 3+3 郵遞區號服務核對寫法並補上郵遞區號，只傳送地址文字。不提供給第三方行銷使用。": "Recipients: Association officers, on a least-privilege basis by role. Sub-club leads and officers can see their own sub-club’s roster (without phone numbers) and the sign-ups and survey results for that sub-club’s events; only administrative staff can see full phone numbers. Race registration details are shared only with the organizing officer of an event you sign up for with group registration and consent to, so they can submit the group entry to the race organizer; every download is audit-logged. Before saving, your mailing address is checked against Chunghwa Post’s 3+3 postal code service to fix its format and add the postal code; only the address text is sent. Nothing is shared with third parties for marketing.",
