"建議在 W13 以後的長跑課，用比賽配速照這個計劃演練一次。一般運動營養建議（ACSM 等），不是醫療建議。": "Rehearse this plan at race pace in a long run from W13 on. General sports-nutrition guidance (ACSM and others), not medical advice.",
"賽前提醒": "Before the race",
"聲明": "Disclaimer",
"這一頁是一般運動研究與營養建議的估算，不是醫療建議，也不是教練規定；課表以教練每週公告為準。懷孕、有慢性病或正在服藥，請先問醫師或營養師。": "This page is an estimate from general exercise research and nutrition guidance — not medical advice and not a coach rule; the coach's weekly post takes priority. If you're pregnant, have a chronic condition or take medication, check with a doctor or dietitian first.",
"資料來源：ACSM 運動營養建議、WMA 2025 路跑年齡分級、Tanaka 最大心率公式。": "Sources: ACSM sports-nutrition guidance, WMA 2025 road age-grading, the Tanaka max-HR formula.",
