"重點課後通常需要 48–72 小時恢復。週二很累時可以改成輕鬆跑，週四團練和週末長跑盡量保留，肌力課不要省略（一般研究建議，請和教練確認）。": "Key sessions usually need 48–72 h of recovery. If Tuesday feels heavy, run it easy; keep Thursday and the weekend long run, and don't skip strength work (general research guidance — check with your coach).",
"注意重點課之間的恢復，每週 1–2 次肌力訓練有助延緩肌肉流失。": "Mind recovery between key sessions; 1–2 strength sessions a week help slow muscle loss.",
