"「可省略」是每週天數不夠時優先省略的輕鬆跑；質量課、長跑和比賽都不省略。錯過的課不要擠到同一天補。": "“Optional” marks easy runs dropped first when you have fewer days; quality sessions, long runs and races are never dropped. Don't cram missed runs into one day.",
