"這份課表只負責整理和換算，不是醫療建議。身體不適、受傷或生病時，請先休息，並跟教練討論。": "This plan only organizes and converts the coach's sessions; it is not medical advice. If unwell, injured or ill, rest first and talk to your coach.",
