"地點卡會列出 1.5 公里內的政府公開攝影機（沒有就列 3 公里內最近一支），畫面由本站轉送、不保存，跑友的 IP 不會送到影像來源。功能開關打開後，鏡頭清單每天清晨 04:00 起自動同步（每小時只同步一個來源，依序是水利署、公路局、水利處）。關掉來源後立即不再顯示，也不再連線。": "Spot cards list public government cameras within 1.5 km (or the nearest one within 3 km if there are none). Images are relayed by this site and not stored, and runners’ IP addresses are never sent to the camera source. Once the feature switch is on, camera lists sync automatically every morning from 04:00 (one source per hour: Water Resources Agency, Highway Bureau, then Taipei Hydraulic Engineering Office). Turning a source off hides it immediately and stops all connections to it.",
"功能開關的「附近即時影像」目前關閉：跑友看不到，排程也不會同步。可以先設定來源、按「立即同步」測試。": "The “Nearby live cameras” feature switch is off: runners can’t see it and scheduled syncs don’t run. You can still set up sources and press “Sync now” to test.",
