"編輯休息站": "Edit rest stop",
"練跑地圖的「休息站」圖層與地點卡的「附近休息站」：政府開放資料加上幹部整理的清單，每筆都標出處與授權。小的來源由排程在清晨自動同步；檔案大或很多檔的來源（Workers 免費方案每次執行只有 10 ms CPU，跑不完）由維護工具在電腦上同步，這裡只顯示上次同步的時間。關掉來源後立即不再顯示，也不再連線。": "The map's “Rest stops” layer and “Nearby rest stops” on spot cards: government open data plus lists curated by officers, each credited with its source and licence. Small sources sync automatically in the early morning; large or multi-file sources (too much for the 10 ms CPU per run on the Workers free plan) are synced on a computer by the maintenance tool, and only their last sync time is shown here. Turning a source off hides it immediately and stops all connections to it.",
