"手機放口袋時畫面全黑、點了沒反應，會盡量讓螢幕保持亮著": "For running with the phone in your pocket: the screen goes black, ignores taps, and tries to stay on",
"口袋模式": "Pocket mode",
"目前配速 /km": "Current pace /km",
