"解鎖口袋模式": "Unlock Pocket mode",
"第一次使用會詢問定位權限。跑步時螢幕會保持亮著；iPhone 鎖定螢幕時收不到定位（計時照走），解鎖後空白的那段用直線估算（路線畫成虛線）。手機放口袋可以開「口袋模式」防誤觸。": "You'll be asked for location access the first time. The screen stays on while you run. If iPhone locks the screen, location stops (the timer keeps going), and the gap is estimated as a straight line once you unlock (drawn dashed on the route). With your phone in a pocket, turn on Pocket mode to avoid accidental taps.",
"螢幕可能會自動關掉": "The screen may turn off on its own",
"iPhone 鎖定螢幕時網頁會停住、收不到定位，解鎖後空白的那段只能用直線估算。想記完整：把「設定 › 螢幕顯示與亮度 › 自動鎖定」暫時設為「永不」；低電量模式下要先關掉低電量模式才能改。": "When iPhone locks the screen, the page pauses and gets no location, so the gap can only be estimated as a straight line after you unlock. To record the whole run, set Settings › Display & Brightness › Auto-Lock to Never while you run. In Low Power Mode, turn Low Power Mode off first, or Auto-Lock can't be changed.",
"也可以再試一次，或開口袋模式（開的時候會再要一次）。": "You can also try again, or turn on Pocket mode (it asks again when it opens).",
"還是沒辦法，請改用自動鎖定設定": "Still not working. Please use the Auto-Lock setting instead",
"螢幕可能會自動關掉，解鎖後再試一次": "The screen may turn off on its own. Unlock and try again",
